def title_of(html: str) -> str:
    """Return the text between <title> and </title> in an HTML string, or an empty string."""
    ex title_of("<html><head><title>Hello World</title></head></html>") == "Hello World"
    ex title_of("<html><body>No title</body></html>") == ""
    _, sep, rest = html.partition("<title>")
    if sep == "":
        _, sep, rest = html.partition("<TITLE>")
        if sep == "":
            return ""
    title, end_sep, _ = rest.partition("</title>")
    if end_sep == "":
        title, end_sep, _ = rest.partition("</TITLE>")
        if end_sep == "":
            return ""
    return title

